    "text": "새벽, 썰물. 산호 여울이 활 두 바탕 넘게 드러났다. 보트들이 멀리 멈추고, 쇠갑옷의 사내들이 허리까지 물에 잠긴 채 걸어 나간다. 해변에서 천오백 명이 넘는 막탄의 전사들이 세 무리로 달려 나온다."
