    "text": "(부채를 부치며 사내들 뒤에서 나선다) 진수 태감 기용이다. 구천세의 명으로 요동의 공을 살피러 왔지. 영원성의 승리는 구천세의 위엄이 하늘에 닿은 덕 — 그렇게 북경에 아뢰었다. 그런데 저 오랑캐 계집이 「누르하치를 맞힌 건 내 포탄」이라며 떠들고 다닌다지 뭐냐. 계집이, 그것도 서양 계집이 성벽에 올랐다는 말이 북경에 들어가면 구천세의 공이 웃음거리가 된다. 입을 막아야지. (성문 쪽에서 굳은 얼굴로 다가오며) 태감, 저 아이는 내 성의 포수요. 성을 지킨 사람을 내 손으로 내줄 수는 없소. …그러나 나는 태감의 붓 한 자루를 이길 힘이 없소."
