    "name": "빈 맥주 통",
    "story": "루터의 종교 개혁",
    "text": "(무릎을 꿇고) …각하께서 시키신 일이오! 나는 날짜를 적었을 뿐이오! 모두 말하겠소! 열흘 뒤. 대주교의 법정이 열렸다. 루프레히트의 자백과 친필 장부 앞에서 그라우엔펠스 추기경은 말을 잃었다. 그는 로마로 소환되었고, 백지 면죄부 수백 장은 성당 마당에서 불태워졌다. 콘라트는 과부에게 비단 값을 물어 주었고, 쿠르트는 농부의 헛간을 다시 지어야 했다. (빈 맥주 통 하나를 툭툭 두드리며) 선장, 부탁이 하나 있어요. 이 수녀원에 더는 있고 싶지 않아요. 저 통 하나만 빌려줘요. 수레에 실려 성문을 나가면… 아무도 수녀 하나가 맥주 통에 들어 있을 줄은 모를 거예요."
