    "text": "(유창하지는 않지만 또박또박한 광동말로) 우리는 명나라 땅 안으로 들어가고 싶습니다. 오문은 문 앞일 뿐이니까요. 조경의 지부 왕반 대인이 서양의 신기한 물건을 보고 싶어 한답니다. 문제는 둘이오. 서강을 거슬러 조경까지 데려다줄 배가 없고, 지부께 바칠 자명종이 아직 인도에서 오지 않았소. 리치가 가진 삼릉경(프리즘) 하나로는 모자라오."
