    "text": "밤, 제독의 배. 식구들은 작은 배로 갈아타고 치리웅 강을 거슬러 올라갔다. 뱃전에 붉은 사롱의 아가씨 하나만 남았다. 아버지는 파쿠안으로 가셨어요. 돌기둥 곁을 떠나지 않겠다고 고집하시다가, 「네가 살아야 순다클라파의 장부가 산다」시면서요. (야자 종이 한 장을 펼친다) 이건 돌기둥의 글을 뜬 탁본이에요. 그날 통역을 하고 몰래 떠 두었어요. 약속이란 게 어떻게 생겼는지 잊지 않으려고요."
