    "text": "반텐 앞바다. 돛이 찢기고 돛대 하나가 부러진 포르투갈 나우 한 척이 비틀거리며 닻을 내린다. 고아를 떠난 프란시스쿠 드 사의 함대에서 떨어져 나온 배라고 한다. (보트를 타고 다가와, 지친 얼굴로) 두아르트 코엘류요. 순다클라파에 요새를 지으러 왔소. 폭풍에 함대가 흩어졌지. 저 동쪽 항구에 우리 동맹이 기다리고 있을 거요. 물을 좀 얻을 수 있겠소? (코엘류의 배를 보며 낮게) 다섯 해예요. 다섯 해나 늦었어요. 아버지는 그 돌기둥 곁에서 저 배를 기다리셨는데."
