    "text": "포르투갈 요새(아 파모자)의 그늘이 드리운 말라카의 중국인 골목. 약재 가게 앞에서 무명 사롱으로 몸을 감싼 젊은 여인이 은을 셈하고 있다. 쓰개 아래로 옻칠처럼 검은 눈이 보인다. 여인이 제독을 보더니 은을 떨어뜨린다. 그리고 천천히 — 제독의 소매 끝을 손가락 두 개로 집는다. 열다섯 해 전, 노란 휘장의 보트에서 누군가 그랬던 것처럼. (떨리는 목소리로) …선장님. 기억 못 하시죠? 그 밤 노란 휘장 보트에서 선장님 소매를 놓지 않던 여덟 살 아이요. 툰 파티마 마마 품에서 울던. 쿠말라예요."
