    "text": "수마트라 캄파르 강의 대나무 궁. 기침 소리가 그치지 않는 방에, 노란 비단을 덮은 늙은 술탄이 누워 있다. 곁에 한 여인이 앉아 있다 — 깊은 그늘이 진, 그러나 아직도 해협 제일이라 할 만한 얼굴이다. (쉰 목소리로) 바다의 선장인가… 나는 말라카를 잃은 술탄이오. 아니, 그 전에 잃은 것이 있지. 나는 이 사람의 아버지를 죽였소. 툰 무타히르 — 나라에서 가장 부유하고 가장 바른 벤다하라를. 그리고 그 딸을 빼앗았지. 포르투갈이 오기 전에 말라카는 이미 무너지고 있었소. 내 손으로. (기침) …내 아들 알리를 부탁하오. 그 아이는 내 죄를 모르고 자라야 하오."
