    "text": "말라카 앞바다, 해 질 녘. 붉은 머리띠의 사내가 모는 날렵한 프라후 한 척이 제독의 배 옆에 붙는다. 뱃머리에 노란 비단의 여인이 서 있다. 락사마나 항 나딤이오. 요새의 눈을 피해 오느라 해가 지기를 기다렸소. 그대에게 청할 일이 있다는 분이 계시오. 캄파르에서 옛 술탄 전하께서 돌아가셨어요. 이제 마르훔 캄파르 — 「캄파르에서 돌아가신 분」이라고 불러요. 라자 알리 전하는 열다섯이세요."
