    "text": "히라도. 포구를 메운 배마다 같은 깃발이 걸렸다. 언덕 위 저택에서는 비단옷의 중국 상인과 칼을 찬 일본 무사, 포르투갈 뱃사람이 한 상에 앉아 술을 마신다. 어서 오시오, 서쪽 바다의 선장. 나는 왕직이오. 휘주의 소금 장수였지. 사람들은 나를 「휘왕」이라 부르고, 명의 관리들은 「왜구의 괴수」라 부르오. (웃는다) 어느 쪽이든 상관없소. 명나라 조정은 바다에 나가는 배를 모두 도적이라 하오. 그러니 장사꾼이 도적이 될 수밖에. 해금을 풀어 주면 나는 내일이라도 이 바다의 도적을 다 잡아 바치겠소. …그런데 조정은 칼만 보내지."
